﻿# --- BOOTSTRAP: Import ConfigMerge module ---
$TestRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$ModulePath = Join-Path $TestRoot '..\..\Projects\Tooling\modules\ConfigMerge\ConfigMerge.psm1'
Import-Module $ModulePath -Force

if (-not (Get-Command Get-ConfigMergeHelp -ErrorAction SilentlyContinue)) {
    throw "Get-ConfigMergeHelp is NOT imported. ModulePath = $ModulePath"
}

Describe 'ConfigMerge Get-ConfigMergeHelp' {
    It 'returns a non-empty help string' {
        $out = Get-ConfigMergeHelp
        $out | Should -Not -BeNullOrEmpty
        $out | Should -Match 'Conflict resolution options'
    }

    It 'supports verbose example output' {
        $out = Get-ConfigMergeHelp -VerboseOutput
        $out | Should -Match 'Example usage'
    }

    It 'documents conflict mode APIs' {
        $out = Get-ConfigMergeHelp
        $out | Should -Match 'Get-ConflictModeManifest'
        $out | Should -Match 'Set-ConflictMode'
    }
}
